import{ActionFormData}from"@minecraft/server-ui";import{getDynamicPropertyKey,setAksesoris,isAllowed}from"./buahBuahApaYangBisaDigorengJawabanNyaJillKawir.js";import{world,system}from"@minecraft/server";const GRIP_ITEM_MAP={0:null,1:"krep:afg",2:"krep:kacgrip",3:"krep:gripod",};const SCOPE_ITEM_MAP={0:null,1:"krep:eotech",2:"krep:compm4",3:"krep:sight1p87",7:"krep:acog",13:"krep:m157",};const LASER_ITEM_MAP={0:null,1:"krep:anpeq",};const MUZZLE_ITEM_MAP={0:null,1:"krep:stdsup",2:"krep:ngswsup",3:"krep:heavysup",};function getCurrentAttachment(player,itemId,attachmentType){const key=getDynamicPropertyKey(itemId);if(!key)return 0;const[grip=0,laser=0,muzzle=0,scope=0]=(player.getDynamicProperty(key)?.split(",")||[]).map(Number);switch(attachmentType){case"grip":return grip;case"laser":return laser;case"muzzle":return muzzle;case"scope":return scope;default:return 0;}}
function findItemInInventory(player,typeId){const inventory=player.getComponent("minecraft:inventory");if(!inventory)return null;const container=inventory.container;for(let slot=0;slot<container.size;slot++){const item=container.getItem(slot);if(item&&item.typeId===typeId){return{container,slot,item};}}
return null;}
function consumeItemFromInventory(player,typeId){const found=findItemInInventory(player,typeId);if(!found)return false;const{container,slot,item}=found;if(item.amount>1){item.amount-=1;container.setItem(slot,item);}else{container.setItem(slot,undefined);}
return true;}
function giveItemToPlayer(player,typeId){if(!typeId)return;player.runCommand(`give @s ${typeId} 1`);}
function processAttachmentChange(player,itemId,attachmentType,newValue,itemMap){const currentValue=getCurrentAttachment(player,itemId,attachmentType);if(newValue===currentValue)return true;const newItemId=itemMap[newValue]??null;const oldItemId=itemMap[currentValue]??null;if(newValue!==0&&newItemId){const found=findItemInInventory(player,newItemId);if(!found){player.sendMessage(`§cYou need §e${newItemId}§c in your inventory to equip this attachment!`);return false;}
consumeItemFromInventory(player,newItemId);}
if(oldItemId){giveItemToPlayer(player,oldItemId);}
setAksesoris(player,itemId,{[attachmentType]:newValue});return true;}
const playersInPreview=new Set();function enterPreview(player){player.addTag("preview_active");player.runCommand("event entity @s krep:view");playersInPreview.add(player.id);}
function exitPreview(player){player.removeTag("preview_active");playersInPreview.delete(player.id);player.runCommand("event entity @s krep:noview");}
function attachmentnew(player){let form=new ActionFormData();form.title("Attachment");form.body("Not sure this mechanic still relevant, but ya, i dont have any time to made this mechanic more advance");form.button('HK416','textures/items/hk416');form.show(player).then(r=>{if(r.canceled)return;switch(r.selection){case 0:hk416att(player);break;default:break;}});}
function m8att(player){const equipped=player.getComponent("minecraft:equippable");const item=equipped.getEquipment("Mainhand");const itemId=item?.typeId;if(!itemId||!isAllowed(itemId)||(itemId!=="krep:m8"&&itemId!=="krep:m8_emp")){player.sendMessage("You must be holding an m8 to use this form!");return;}
enterPreview(player);const form=new ActionFormData();form.title("kanjut");form.body("Select an attachment type to customize your M8 Carbine.");form.button("Grip","textures/ui/grip1");form.button("Laser","textures/ui/laser1");form.button("Muzzle","textures/ui/muzzle1");form.button("Sight","textures/ui/scope1");form.show(player).then((response)=>{exitPreview(player);if(response.canceled)return;switch(response.selection){case 0:m8attgrip(player);break;case 1:m8attlaser(player);break;case 2:m8attmuzzle(player);break;case 3:m8attscope(player);break;}});}
